from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        S_r = str(r)
        S_l = str(l - 1)
        max_sum = 9 * len(S_r)

        total_r = 0
        total_l = 0

        # Group evaluations to share the DP cache between `r` and `l - 1` for each target sum
        for target_sum in range(1, max_sum + 1):

            # Pure unconstrained digit DP state: relies solely on length, sum, and product modulo
            @lru_cache(None)
            def dp(rem_len: int, cur_sum: int, prod_mod: int) -> int:
                if rem_len == 0:
                    return 1 if cur_sum == target_sum and prod_mod == 0 else 0

                ans = 0
                for d in range(10):
                    next_sum = cur_sum + d
                    # Pruning: ensure target_sum is still mathematically reachable
                    if next_sum <= target_sum and next_sum + 9 * (rem_len - 1) >= target_sum:
                        next_prod = (prod_mod * d) % target_sum
                        ans += dp(rem_len - 1, next_sum, next_prod)
