                    cur_sum += limit
                    cur_prod = (cur_prod * limit) % target_sum

                    if cur_sum > target_sum:
                        break
                else:
                    # Final check for the exact number represented by string `S`
                    if cur_sum == target_sum and cur_prod == 0:
                        total += 1

                return total

            total_r += count_for_target(S_r)
